  const [filter, setFilter] = useState<Row>({ notWorkOrderId: order.workOrderId, contractEffectiveDateString: str(order, 'workOrderOpenDateString'), burialSiteName: '', deceasedName: '', burialSiteStatusId: '', offset: 0, limit: 100 })
  const { result, error, reload } = useLoad(contracts ? '/api/contracts/search' : '/api/burialSites/doSearchBurialSites', filter)
  const [saveError, setSaveError] = useState<unknown>(null)
