  const other = rows(conflicts || {}, 'workOrderMilestones').filter((row) => str(row, 'workOrderId') !== str(order, 'workOrderId'))
  return <Modal title={l(edit ? 'editMilestone' : 'addMilestone')} onClose={onClose}><div className="two-columns"><form id={`form--${prefix}`} onSubmit={save}><fieldset disabled={busy}><Field name={`${prefix}--workOrderMilestoneTypeId`} label={l('milestoneType')}><select autoFocus id={`${prefix}--workOrderMilestoneTypeId`} name="workOrderMilestoneTypeId" value={str(form, 'workOrderMilestoneTypeId')} onChange={(e) => setForm((old) => ({ ...old, workOrderMilestoneTypeId: e.target.value }))}><option value="">{l('noType')}</option><Options options={options} list="workOrderMilestoneTypes" id="workOrderMilestoneTypeId" text="workOrderMilestoneType" current={item} /></select></Field><div className="two-columns">{input('workOrderMilestoneDateString', l('milestoneDate'), { type: 'date', required: true, min: openDate })}{input('workOrderMilestoneTimeString', l('milestoneTime'), { type: 'time' })}</div>{outside && <p className="warning-text" id={`${prefix}--workOrderMilestoneDateTimeMessage`}>{l('outsideHours')}</p>}<Field name={`${prefix}--workOrderMilestoneDescription`} label={t('description')}><textarea id={`${prefix}--workOrderMilestoneDescription`} name="workOrderMilestoneDescription" value={str(form, 'workOrderMilestoneDescription')} onChange={(e) => setForm((old) => ({ ...old, workOrderMilestoneDescription: e.target.value }))} /></Field>{Boolean(error) && <ErrorMessage error={error} t={t} />}<div className="actions"><button type="button" onClick={onClose}>{t('cancel')}</button><button className="primary" type="submit">{l(edit ? 'updateMilestone' : 'addMilestone')}</button></div></fieldset></form><Panel title={l('conflicts')}>{!conflicts ? <Pending error={conflictError} t={t} /> : !other.length ? <p>{l('noConflicts')}</p> : other.map((row) => <p key={str(row, 'workOrderMilestoneId')}>{str(row, 'workOrderMilestoneTimePeriodString') || l('noTime')}<br /><strong>{str(row, 'workOrderMilestoneType')}</strong><br /><Link href={`/workOrders/${row.workOrderId}`}>#{str(row, 'workOrderNumber')}</Link><br />{str(row, 'workOrderDescription')}</p>)}</Panel></div></Modal>
