  return <Modal title={l('updateTime')} onClose={onClose}><form id="form--workOrderMilestoneUpdate" onSubmit={save}><fieldset disabled={busy}><Field name="workOrderMilestoneUpdate--workOrderMilestoneDateString" label={l('milestoneDate')}><div className="input-addons"><input id="workOrderMilestoneUpdate--workOrderMilestoneDateString" name="workOrderMilestoneDateString" type="date" defaultValue={date} readOnly={!unlocked} required /><button type="button" title={l('unlockDate')} aria-label={l('unlockDate')} onClick={() => setUnlocked(true)}>🔓</button></div></Field><Field name="workOrderMilestoneUpdate--workOrderMilestoneTimeString" label={l('milestoneTime')}><input autoFocus id="workOrderMilestoneUpdate--workOrderMilestoneTimeString" name="workOrderMilestoneTimeString" type="time" step={900} defaultValue={milestone.workOrderMilestoneTime == null ? '' : str(milestone, 'workOrderMilestoneTimeString')} /></Field>{Boolean(error) && <ErrorMessage error={error} t={t} />}<div className="actions"><button type="button" onClick={onClose}>{t('cancel')}</button><button className="primary" type="submit">{l('updateTime')}</button></div></fieldset></form></Modal>
